#include <iostream>
#include <vector>
#include <algorithm>
int main() {
    std::vector<int> v = {1,2,3,4,5,6,7,8};
    auto mid = std::stable_partition(v.begin(), v.end(), [](int x){ return x % 2 == 0; });
    std::cout << "边界前(偶数): ";
    for (auto it = v.begin(); it != mid; ++it) std::cout << *it << ' ';
    std::cout << "\n边界后: ";
    for (auto it = mid; it != v.end(); ++it) std::cout << *it << ' ';
    std::cout << '\n';
    std::cout << "偶数个数 = " << (mid - v.begin()) << '\n';
}
